/**
 * Bill of materials for those who actually have to buy and assemble the board.
 *
 * The one generated by the standard library listed one row per designator,
 * with no manufacturer part number, no aggregated quantities and not a single
 * link: an assembler cannot place an order from that. Here rows are grouped
 * by identical part (the way a purchasing office reads them), each row
 * carries the exact code to order and the links to verify it, and
 * non-orderable components are flagged instead of silently blank.
 *
 * The Comment / Designator / Footprint / LCSC Part # columns keep the names
 * JLCPCB assembly expects, so the file can be uploaded as-is; the others are
 * appended at the end and ignored by those who do not use them.
 */

import { analyzeFootprints } from "./footprint-provenance";

interface El {
  type: string;
  [key: string]: unknown;
}

export interface BomLine {
  /** aggregated designators, e.g. "C1,C2,C3" */
  designators: string;
  quantity: number;
  value: string;
  package: string;
  manufacturerPartNumber: string;
  lcsc: string;
  /** equivalent part numbers, for when the first one is out of stock */
  alternatives: string;
  /** product page: contains price, availability and datasheet */
  lcscUrl: string;
  /** part page in the JLCPCB assembly catalog */
  jlcpcbUrl: string;
  /** empty if orderable, otherwise says what is missing */
  note: string;
}

const lcscUrl = (code: string) =>
  code ? `https://www.lcsc.com/product-detail/${code}.html` : "";
const jlcpcbUrl = (code: string) =>
  code ? `https://jlcpcb.com/partdetail/${code}` : "";

/** sorts designators the way a person would: C2 before C10 */
function byDesignator(a: string, b: string): number {
  const [, pa = "", na = "0"] = /^([A-Za-z_]*)(\d*)/.exec(a) ?? [];
  const [, pb = "", nb = "0"] = /^([A-Za-z_]*)(\d*)/.exec(b) ?? [];
  return pa === pb ? Number(na) - Number(nb) : pa.localeCompare(pb);
}

export function buildBom(circuitJson: El[], sources: Record<string, string> = {}): BomLine[] {
  const footprintOf = new Map(
    analyzeFootprints(circuitJson, sources).records.map((r) => [r.component, r]),
  );

  interface Group {
    designators: string[];
    value: string;
    package: string;
    mpn: string;
    lcsc: string;
    alternatives: string;
  }
  const groups = new Map<string, Group>();

  for (const el of circuitJson) {
    if (el.type !== "source_component") continue;
    const name = String(el.name ?? "");
    if (!name) continue;

    const record = footprintOf.get(name);
    const supplier = el.supplier_part_numbers as Record<string, unknown> | undefined;
    const jlc = supplier?.jlcpcb;
    const codes = Array.isArray(jlc) ? jlc.filter((c): c is string => typeof c === "string") : [];
    const lcsc = codes[0] ?? record?.lcsc ?? "";
    // the alternates really matter: when the first one is out of stock, the
    // purchasing office immediately has the equivalent part numbers instead of starting over
    const alternatives = codes.slice(1, 4).join(" ");
    const mpn = String(el.manufacturer_part_number ?? "");
    // each family exposes its own readable field: without this the
    // value column stayed empty and the BOM was useless
    const value = String(
      el.display_capacitance ??
        el.display_resistance ??
        el.display_inductance ??
        el.display_value ??
        el.symbol_display_value ??
        "",
    );
    const pkg = record?.footprint ?? "";

    // same part = same row: that is how you order and assemble
    const key = [value, pkg, mpn, lcsc].join("\0");
    const group = groups.get(key) ?? { designators: [], value, package: pkg, mpn, lcsc, alternatives };
    group.designators.push(name);
    groups.set(key, group);
  }

  return [...groups.values()]
    .map((g) => ({
      designators: g.designators.sort(byDesignator).join(","),
      quantity: g.designators.length,
      value: g.value,
      package: g.package,
      manufacturerPartNumber: g.mpn,
      lcsc: g.lcsc,
      alternatives: g.alternatives,
      lcscUrl: lcscUrl(g.lcsc),
      jlcpcbUrl: jlcpcbUrl(g.lcsc),
      note: g.lcsc
        ? ""
        : "NON ORDINABILE: manca il codice LCSC, va scelto un part reale prima di produrre",
    }))
    .sort((a, b) => byDesignator(a.designators, b.designators));
}

const CSV_HEADER = [
  "Comment",
  "Designator",
  "Footprint",
  "LCSC Part #",
  "Quantity",
  "Manufacturer Part Number",
  "Alternative LCSC",
  "LCSC URL",
  "JLCPCB URL",
  "Note",
];

/*
 * A CELL IS DATA, NEVER A FORMULA. A component value or a part number comes
 * from the project sources, which the agent and anyone with edit access write:
 * a value like `=HYPERLINK(...)` opened in Excel or Sheets by the purchasing
 * office runs as a formula (CSV injection, OWASP). A text starting with one of
 * the characters a spreadsheet reads as a formula gets a leading apostrophe,
 * which every spreadsheet shows as plain text. Numbers stay numbers.
 */
const FORMULA = /^[=+\-@\t\r]/;
export const csvCell = (v: string | number): string => {
  const text = typeof v === "number" ? String(v) : FORMULA.test(v) ? `'${v}` : v;
  return `"${text.replace(/"/g, '""')}"`;
};
const cell = csvCell;

export function bomToCsv(lines: BomLine[]): string {
  const rows = lines.map((l) =>
    [
      l.value || l.manufacturerPartNumber,
      l.designators,
      l.package,
      l.lcsc,
      l.quantity,
      l.manufacturerPartNumber,
      l.alternatives,
      l.lcscUrl,
      l.jlcpcbUrl,
      l.note,
    ]
      .map(cell)
      .join(","),
  );
  return [CSV_HEADER.map(cell).join(","), ...rows].join("\n") + "\n";
}

/** a pick-and-place row, as circuit-json-to-pnp-csv reads it from the board */
export interface PnpRow {
  designator: string;
  mid_x: number;
  mid_y: number;
  /** a layer name, or the `{ name }` object some circuit-json versions write */
  layer: unknown;
  rotation: number;
}

/** rotation in [0, 360): what an assembly machine expects, whatever the CAD wrote */
export function normalizeRotation(deg: unknown): number {
  const v = typeof deg === "number" && Number.isFinite(deg) ? deg : 0;
  const r = ((v % 360) + 360) % 360;
  // three decimals, like the coordinates; and never a 360 out of a rounding
  const tondo = Math.round(r * 1000) / 1000;
  return tondo >= 360 ? 0 : tondo;
}

/**
 * WHERE THE MACHINE PUTS THE PART.
 *
 * circuit-json-to-pnp-csv writes `pcb_component.center`: the middle of the box
 * around the footprint. For a symmetric part that is the body. For a footprint
 * whose pads are not symmetric it is not: on BIRDY_BAT (2026-10-20) the two MEMS
 * microphones, with their pads at one end and the acoustic ring at the other,
 * came out 0.41 and 0.36 mm away from the body, enough to move the sound port
 * off its hole in the board; an EMI filter array 0.2 mm.
 *
 * IPC-7351, and every CAD library that follows it, puts the origin of a
 * surface-mount footprint at the centre of the body, and the origin is where
 * the design placed the part (pcbX/pcbY, `display_offset_*`). So for parts
 * without plated holes the origin is used. Through-hole parts keep the
 * library's value: a connector is often drawn from pin 1 (the JST XH on the
 * same board has its origin 3.75 mm from the middle of its pins), and there
 * the box of the pads is the better guess.
 */
export function centriDiMontaggio(rows: PnpRow[], circuitJson: readonly unknown[]): PnpRow[] {
  type El = { type?: unknown; [k: string]: unknown };
  const els = circuitJson as El[];
  const nome = new Map<string, string>();
  for (const e of els) {
    if (e.type === "source_component" && typeof e.source_component_id === "string") {
      nome.set(e.source_component_id, String(e.name ?? ""));
    }
  }
  const conFori = new Set<string>();
  for (const e of els) {
    if (e.type === "pcb_plated_hole" && typeof e.pcb_component_id === "string") conFori.add(e.pcb_component_id);
  }
  const origine = new Map<string, { x: number; y: number }>();
  for (const e of els) {
    if (e.type !== "pcb_component" || typeof e.pcb_component_id !== "string") continue;
    const x = e.display_offset_x;
    const y = e.display_offset_y;
    const n = nome.get(String(e.source_component_id ?? ""));
    if (!n || conFori.has(e.pcb_component_id)) continue;
    if (typeof x === "number" && Number.isFinite(x) && typeof y === "number" && Number.isFinite(y)) {
      origine.set(n, { x, y });
    }
  }
  return rows.map((r) => {
    const o = origine.get(String(r.designator ?? ""));
    return o ? { ...r, mid_x: o.x, mid_y: o.y } : r;
  });
}

/**
 * The pick-and-place file, same columns as circuit-json-to-pnp-csv writes
 * (Designator, Mid X, Mid Y, Layer, Rotation), with two differences that
 * matter on the factory side: text cells cannot be formulas (see csvCell), and
 * the rotation is brought into [0, 360) — a -90 or a 450 written by another CAD
 * is a valid angle that some assembly uploads reject. Coordinates are numbers
 * and are written as they are: a negative coordinate is not a formula.
 */
export function pnpToCsv(rows: PnpRow[]): string {
  // the header as the library wrote it: some assembly uploads match it literally
  const header = "Designator,Mid X,Mid Y,Layer,Rotation";
  const lines = rows.map((r) =>
    [
      cell(String(r.designator ?? "")),
      Number(r.mid_x ?? 0).toFixed(3),
      Number(r.mid_y ?? 0).toFixed(3),
      cell(
        typeof r.layer === "object" && r.layer !== null
          ? String((r.layer as { name?: unknown }).name ?? "")
          : String(r.layer ?? ""),
      ),
      String(normalizeRotation(r.rotation)),
    ].join(","),
  );
  return [header, ...lines].join("\r\n");
}
